<!doctype html><title><?=$title?></title><style>body{font:16px Arial;margin:40px}form{max-width:600px}input,textarea,button{width:100%;box-sizing:border-box;padding:10px;margin:7px 0}button{background:#4f46e5;color:white;border:0}.e{color:#b00}</style><a href="<?=site_url('products')?>">← Products</a><h1><?=$title?></h1><?php if($error):?><p class=e><?=$error?></p><?php endif?><form method=post action="<?=site_url($action)?>"><input name=product_name required placeholder="Product name" value="<?=htmlspecialchars($product['product_name']??'')?>"><textarea name=description placeholder=Description><?=htmlspecialchars($product['description']??'')?></textarea><input name=price type=number min=0 step=.01 required placeholder=Price value="<?=htmlspecialchars($product['price']??'')?>"><input name=quantity type=number min=0 required placeholder=Quantity value="<?=htmlspecialchars($product['quantity']??'')?>"><button>Save product</button></form>
